// Copyright 2026 Anthropic PBC
// SPDX-License-Identifier: Apache-2.0
// Modified by Verselo Systems SL, 2026: German UI, readability, fixes (see NOTICE.md)
//
// Replay Theater: records the file edits Claude makes in a turn, then lets you
// step through them in a pane, one diff at a time. Inside a git repo it also
// picks up files changed by shell commands (sed -i, mv, codemods).
//
// Claude Code function hooks. Load with --plugin-dir.

import { MAX_DIFF_LINES, diffLines, countChanges, parseUnifiedDiff, parseStatusZ, splitGitDiff } from "./diff.mjs";

const PANE_ID = "replay-theater";
const EDIT_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
const MAX_SHELL_FILES = 20;
const GIT_TIMEOUT_MS = 5000;
const MAX_STRIP_CELLS = 15;

// Module state. `pending` fills during a turn; `replay` is the last finished
// turn's steps, the ones the pane shows. `snap` is the git snapshot taken when
// the main-loop turn started (null outside a git repo).
const state = { pending: [], replay: [], index: 0, isOpen: false, inBand: false, turns: 0, snap: null };

function relPath(cwd, path) {
  if (!path) return "(unbekannte Datei)";
  if (cwd && path.startsWith(cwd + "/")) return path.slice(cwd.length + 1);
  return path;
}

function plural(n) {
  return `${n} Änderung${n === 1 ? "" : "en"}`;
}

async function sessionCwd($) {
  try { return (await $.session.cwd()) || ""; } catch { return ""; }
}

// Turns one tool call into one or more steps. `abs` is kept so the shell
// detection can skip files an edit tool already recorded.
async function stepsFor($, e) {
  const cwd = await sessionCwd($);
  const file = relPath(cwd, e.file_path);
  const abs = e.file_path;
  if (e.tool === "Edit") {
    return [{ tool: "Edit", file, abs, diff: diffLines(e.old_string, e.new_string), note: e.replace_all ? "alles ersetzt" : "" }];
  }
  if (e.tool === "MultiEdit" && Array.isArray(e.edits)) {
    return e.edits.map((ed, k) => ({
      tool: "MultiEdit", file, abs, diff: diffLines(ed.old_string, ed.new_string), note: `Bearbeitung ${k + 1} von ${e.edits.length}`,
    }));
  }
  if (e.tool === "Write") {
    let before = "";
    let isNew = true;
    try {
      if (e.file_path && (await $.fs.exists(e.file_path))) {
        before = await $.fs.read(e.file_path);
        isNew = false;
      }
    } catch { /* unreadable: show it as a new file */ }
    return [{ tool: "Write", file, abs, diff: diffLines(before, e.content), note: isNew ? "neue Datei" : "überschrieben" }];
  }
  return [];
}

// --- Shell changes (git) ---------------------------------------------------

async function git($, cwd, args) {
  return $.process.run(["git", ...args], { cwd, timeoutMs: GIT_TIMEOUT_MS });
}

// The repo's state: its top folder, each changed path's status code and its
// `git diff` chunk. null outside a git repo, or when git fails.
async function gitSnapshot($) {
  try {
    const cwd = await sessionCwd($);
    if (!cwd) return null;
    const top = await git($, cwd, ["rev-parse", "--show-toplevel"]);
    if (top.exitCode !== 0) return null;
    const root = top.stdout.trim();
    const [status, diff] = await Promise.all([
      git($, root, ["status", "--porcelain", "-z", "--untracked-files=all"]),
      git($, root, ["-c", "core.quotePath=false", "diff", "--no-color", "--no-ext-diff"]),
    ]);
    if (status.exitCode !== 0 || diff.exitCode !== 0) return null;
    return { cwd, root, status: parseStatusZ(status.stdout), chunks: splitGitDiff(diff.stdout) };
  } catch {
    return null;
  }
}

// One "Shell" step per file whose status or diff changed between the two
// snapshots and that no edit tool recorded this turn. At most 20 files.
async function shellSteps($, before, after, recorded) {
  if (!before || !after || before.root !== after.root) return [];
  const key = (snap, p) => `${snap.status.get(p) ?? ""}\0${snap.chunks.get(p) ?? ""}`;
  const paths = [...new Set([...before.status.keys(), ...after.status.keys()])]
    .filter((p) => key(before, p) !== key(after, p))
    .filter((p) => !recorded.has(`${after.root}/${p}`))
    .sort()
    .slice(0, MAX_SHELL_FILES);
  const steps = [];
  for (const p of paths) {
    const abs = `${after.root}/${p}`;
    const code = after.status.get(p);
    let text = after.chunks.get(p) ?? "";
    let note = "";
    if (code === "??") {
      // Untracked: plain `git diff` shows nothing, so diff against nothing.
      note = "neue Datei";
      try {
        text = (await git($, after.root, ["diff", "--no-color", "--no-ext-diff", "--no-index", "--", "/dev/null", p])).stdout;
      } catch { text = ""; }
    } else if (code === undefined) {
      note = "zurückgesetzt";
    } else if (code.includes("D")) {
      note = "gelöscht";
    }
    steps.push({ tool: "Shell", file: relPath(after.cwd, abs), abs, diff: parseUnifiedDiff(text), note });
  }
  return steps;
}

// --- UI --------------------------------------------------------------------

function hintText() {
  return `▶ Replay: ${plural(state.replay.length)} (r drücken)`;
}

async function openReplay($) {
  if (!state.replay.length) return false;
  state.index = 0;
  state.isOpen = true;
  // The pane only takes the keyboard while nothing else holds it. Hide the
  // band first (it held the keys if its button was pressed), then open.
  $.ui.invalidate("ui.render");
  await $.clock.sleep(200);
  const rows = Math.min(MAX_DIFF_LINES + 9, 23);
  const placed = await $.ui.open({ id: PANE_ID, title: "Replay Theater", focus: true, closeOnEscape: true, rows, columns: 64 });
  // No room for a pane (a narrow terminal): draw the replay in the band.
  state.inBand = placed?.isPlaced === false;
  $.ui.invalidate("ui.render");
  return true;
}

// Which step numbers the strip shows: all of them when they fit, else a
// window around the current one.
function stripWindow(k, total) {
  if (total <= MAX_STRIP_CELLS) return { from: 0, to: total };
  const from = Math.max(0, Math.min(k - Math.floor(MAX_STRIP_CELLS / 2), total - MAX_STRIP_CELLS));
  return { from, to: from + MAX_STRIP_CELLS };
}

// The replay view: one step at a time. Drawn in the Pane, or in the band
// above the prompt when the surface can't place a pane.
function replayView($, e, inBand) {
  const { Box, Text, Button } = $.ui.resolve(e);
  const maxDiff = inBand ? Math.max(3, Math.min(MAX_DIFF_LINES, (e.maxRows || 20) - 8)) : MAX_DIFF_LINES;
  const total = state.replay.length;
  if (!total) return Text({ dimColor: true, children: "Keine Änderungen zum Abspielen." });
  const k = Math.max(0, Math.min(state.index, total - 1));
  const step = state.replay[k];
  const width = Math.max(40, (e.bodyColumns || 100) - 4);
  const { add, del } = countChanges(step.diff);
  const shown = step.diff.slice(0, maxDiff);

  const diffRows = shown.map((l, n) => {
    const color = l.op === "+" ? "green" : l.op === "-" ? "red" : undefined;
    const line = `${l.op === "~" ? " " : l.op} ${l.t}`.slice(0, width);
    return Text({ key: `d${n}`, color, dimColor: l.op === " " || l.op === "~", wrap: "truncate-end", children: line });
  });
  if (step.diff.length > maxDiff) diffRows.push(Text({ key: "more", dimColor: true, children: `  … ${step.diff.length - maxDiff} weitere Zeilen` }));
  if (!shown.length) diffRows.push(Text({ key: "empty", dimColor: true, children: "  (keine Zeilenänderungen)" }));

  // The step strip: one cell per step, the current one highlighted. Many
  // steps scroll in a window with "…" on the cut sides.
  const { from, to } = stripWindow(k, total);
  const strip = [];
  if (from > 0) strip.push(Text({ key: "s-left", dimColor: true, children: " … " }));
  for (let n = from; n < to; n++) {
    strip.push(Text({ key: `s${n}`, inverse: n === k, bold: n === k, color: n === k ? "cyan" : undefined, dimColor: n !== k, children: ` ${n + 1} ` }));
  }
  if (to < total) strip.push(Text({ key: "s-right", dimColor: true, children: " … " }));

  const go = (to) => { state.index = Math.max(0, Math.min(to, total - 1)); $.ui.invalidate("ui.render"); };
  const close = () => {
    state.isOpen = false;
    if (!state.inBand) $.ui.close({ id: PANE_ID });
    state.inBand = false;
    $.ui.invalidate("ui.render");
  };

  return Box({
    flexDirection: "column", borderStyle: "round", borderColor: "magenta", paddingX: 1,
    children: [
      Box({ flexDirection: "row", justifyContent: "space-between", children: [
        Text({ bold: true, color: "magenta", children: "▶ Replay Theater" }),
        Text({ key: "counter", bold: true, children: `Schritt ${k + 1} von ${total}` }),
      ] }),
      Box({ flexDirection: "row", children: strip }),
      // The file is the headline: bold, with its +/- counts right beside it.
      Box({ flexDirection: "row", gap: 2, marginTop: 1, children: [
        Text({ key: "file", bold: true, color: "cyan", wrap: "truncate-start", children: step.file }),
        Text({ key: "add", bold: true, color: "green", children: `+${add}` }),
        Text({ key: "del", bold: true, color: "red", children: `-${del}` }),
      ] }),
      Text({ key: "tool", dimColor: true, children: `${step.tool}${step.note ? " · " + step.note : ""}` }),
      Box({ flexDirection: "column", marginTop: 1, children: diffRows }),
      Box({ flexDirection: "row", gap: 2, marginTop: 1, children: [
        Button({ key: "prev", label: "◀ Zurück", hotkey: "p", onPress: () => go(k - 1) }),
        Button({ key: "next", label: "Weiter ▶", hotkey: "n", autoFocus: true, onPress: () => go(k + 1) }),
        Button({ key: "close", label: "Schließen", hotkey: "c", onPress: close }),
      ] }),
    ],
  });
}

export function register(on, options) {
  // Slash command: /replay opens the pane.
  on("session.start", async ($, e, next) => {
    const r = await next(e);
    try {
      await $.command.register({ name: "replay", description: "Replay Theater: die Änderungen des letzten Turns Schritt für Schritt ansehen" });
    } catch { /* the command is a convenience; the band still works */ }
    return r;
  });

  on("command.run", { command: "replay" }, async ($, e) => {
    const opened = await openReplay($);
    return { text: opened ? `Replay Theater: ${plural(state.replay.length)}` : "Replay Theater: keine Änderungen im letzten Turn." };
  });

  // Record each edit, then let it run. Never blocks the call.
  on("tool.call", async ($, e, next) => {
    if (EDIT_TOOLS.has(e.tool)) {
      try {
        const steps = await stepsFor($, e);
        state.pending.push(...steps);
      } catch { /* recording must never stop the edit */ }
    }
    return next(e);
  });

  // A main-loop turn starts: clear the pending steps and snapshot git, so
  // turn.complete can tell which files shell commands changed.
  on("turn.start", async ($, e, next) => {
    if (!e.agentId) {
      state.pending = [];
      state.snap = await gitSnapshot($);
    }
    return next(e);
  });

  // At the end of a main-loop turn, the pending edits (plus shell changes)
  // become the replay.
  on("turn.complete", async ($, e, next) => {
    const r = await next(e);
    if (e.agentId) return r;
    try {
      const before = state.snap;
      state.snap = null;
      if (before) {
        const recorded = new Set(state.pending.map((s) => s.abs).filter(Boolean));
        state.pending.push(...(await shellSteps($, before, await gitSnapshot($), recorded)));
      }
    } catch { /* shell detection is best effort */ }
    if (!state.pending.length) return r;
    state.replay = state.pending;
    state.pending = [];
    state.index = 0;
    state.turns++;
    $.ui.invalidate("ui.render");
    return r;
  });

  // The band above the prompt: the hint and a button that opens the pane.
  on("ui.render", { component: "AbovePrompt" }, ($, e, next) => {
    if (state.isOpen && state.inBand) return replayView($, e, true);
    if (!state.replay.length || state.isOpen) return next(e);
    const { Box, Text, Button } = $.ui.resolve(e);
    return Box({
      flexDirection: "row", gap: 2, paddingX: 1,
      children: [
        Text({ key: "hint", color: "magenta", bold: true, children: hintText() }),
        Button({ key: "open-replay", label: "Abspielen", hotkey: "r", onPress: () => openReplay($) }),
      ],
    });
  });

  // The pane.
  on("ui.render", { component: "Pane" }, ($, e, next) => {
    if (e.requestId !== PANE_ID) return next(e);
    return replayView($, e, false);
  });

  // The person closed the pane (Escape): keep our flag in step.
  on("ui.close", ($, e, next) => {
    if (e.id === PANE_ID || e.requestId === PANE_ID) state.isOpen = false;
    $.ui.invalidate("ui.render");
    return next(e);
  });
}

