// Copyright 2026 Anthropic PBC
// SPDX-License-Identifier: Apache-2.0
// Modified by Verselo Systems SL, 2026: German UI, readability, fixes (see NOTICE.md)
//
// Pure diff helpers: the line diff for edit tools, and the parsers for git's
// output that the shell-change detection uses. No `$` in here, so the tests
// can call them directly.

export const MAX_DIFF_LINES = 12;
export const MAX_LCS_LINES = 400;

export function splitLines(text) {
  if (text === undefined || text === null || text === "") return [];
  const lines = String(text).split("\n");
  if (lines.length > 1 && lines[lines.length - 1] === "") lines.pop();
  return lines;
}

// A line diff. Small inputs get an LCS diff, so unchanged lines show as
// context; large ones fall back to all-removed then all-added.
export function diffLines(oldText, newText) {
  const a = splitLines(oldText);
  const b = splitLines(newText);
  if (a.length > MAX_LCS_LINES || b.length > MAX_LCS_LINES) {
    return [...a.map((t) => ({ op: "-", t })), ...b.map((t) => ({ op: "+", t }))];
  }
  const n = a.length, m = b.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  const out = [];
  let i = 0, j = 0;
  while (i < n && j < m) {
    if (a[i] === b[j]) { out.push({ op: " ", t: a[i] }); i++; j++; }
    else if (dp[i + 1][j] >= dp[i][j + 1]) out.push({ op: "-", t: a[i++] });
    else out.push({ op: "+", t: b[j++] });
  }
  while (i < n) out.push({ op: "-", t: a[i++] });
  while (j < m) out.push({ op: "+", t: b[j++] });
  return trimContext(out);
}

// Keep one line of context around each change, so a long file's Write shows
// the changed lines, not the whole file. A skipped run becomes one "⋯" row.
export function trimContext(lines) {
  if (!lines.some((l) => l.op !== " " && l.op !== "~")) return lines.slice(0, MAX_DIFF_LINES);
  const changed = (l) => l && l.op !== " " && l.op !== "~";
  const keep = lines.map((l, k) => changed(l) || (l.op === " " && (changed(lines[k - 1]) || changed(lines[k + 1]))));
  const out = [];
  let skipped = false;
  lines.forEach((l, k) => {
    if (keep[k]) { if (skipped && out.length) out.push({ op: "~", t: "⋯" }); out.push(l); skipped = false; }
    else skipped = true;
  });
  return out;
}

export function countChanges(diff) {
  let add = 0, del = 0;
  for (const l of diff) { if (l.op === "+") add++; else if (l.op === "-") del++; }
  return { add, del };
}

// A unified diff (one file's `git diff` output) as {op,t} rows. Header lines
// (diff --git, index, ---/+++, mode lines, @@) are dropped; a gap between two
// hunks becomes one "⋯" row. Then the same context trim as the edit tools.
export function parseUnifiedDiff(text) {
  const out = [];
  let inHunk = false;
  for (const line of String(text ?? "").split("\n")) {
    if (line.startsWith("@@")) {
      if (out.length) out.push({ op: "~", t: "⋯" });
      inHunk = true;
      continue;
    }
    if (!inHunk) continue;
    const c = line[0];
    if (c === "+" || c === "-" || c === " ") out.push({ op: c, t: line.slice(1) });
    else if (line === "") continue; // trailing newline of the output
    else if (c === "\\") continue; // "\ No newline at end of file"
    else inHunk = false; // the next file's "diff --git" header
  }
  return trimContext(out);
}

// `git status --porcelain -z --untracked-files=all` as Map(path -> "XY").
// A rename or copy entry carries its source as one more NUL field; skip it.
export function parseStatusZ(text) {
  const map = new Map();
  const parts = String(text ?? "").split("\0");
  for (let k = 0; k < parts.length; k++) {
    const p = parts[k];
    if (p.length < 4) continue;
    const xy = p.slice(0, 2);
    map.set(p.slice(3), xy);
    if (xy[0] === "R" || xy[0] === "C") k++;
  }
  return map;
}

// A whole `git diff` output split into Map(path -> that file's chunk). The
// path comes from "diff --git a/P b/P"; quoted or renamed headers are skipped
// (ponytail: such files are never told apart, so they never show as Shell).
export function splitGitDiff(text) {
  const map = new Map();
  let path = null, buf = [];
  const flush = () => { if (path !== null) map.set(path, buf.join("\n")); };
  for (const line of String(text ?? "").split("\n")) {
    if (line.startsWith("diff --git ")) {
      flush();
      buf = [];
      const rest = line.slice("diff --git ".length);
      const len = (rest.length - 5) / 2; // "a/P b/P"
      const p = Number.isInteger(len) && len > 0 ? rest.slice(2, 2 + len) : null;
      path = p !== null && rest === `a/${p} b/${p}` ? p : null;
    }
    buf.push(line);
  }
  flush();
  return map;
}

